// ─── File: WorkerRecoveryDemo.java ───
// Layered recovery: retry transient faults → coordinator detects dead node by
// missed heartbeats → Competing Consumers re-drive work → resume from checkpoint.
import java.util.*;
import java.util.logging.*;

public class WorkerRecoveryDemo {
    private static final Logger log = Logger.getLogger("RECOVER");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Layer 1: retry absorbs a transient fault (ledger blips then recovers).
        log.info("=== Layer 1: retry first (most failures are transient) ===");
        RetryExecutor retry = new RetryExecutor(3, 200, true);
        int[] attempt = {0};
        String r = retry.run("ledger-call", () -> {
            attempt[0]++;
            if (attempt[0] < 2) throw new RuntimeException("transient timeout");
            return "ledger ok";
        });
        log.info(() -> "Transient fault recovered by retry: " + r);

        // Layer 2: coordinator detects dead node via missed heartbeats.
        log.info("=== Layer 2: heartbeat detection + Competing Consumers redistribution ===");
        Coordinator coord = new Coordinator(6000);
        WorkQueue queue = new WorkQueue();
        long t = 1_000_000L;
        coord.heartbeat("worker-A", t); coord.heartbeat("worker-B", t);

        // worker-A claims the long reconciliation job.
        queue.enqueue("reconcile-EOD");
        String claimed = queue.claim("worker-A", t);
        log.info(() -> "worker-A claimed " + claimed);

        // worker-A dies: stops heartbeating; worker-B keeps beating.
        long later = t + 7000;   // > session timeout
        coord.heartbeat("worker-B", later);
        List<String> dead = coord.detectDead(later);
        dead.forEach(d -> {
            log.severe(() -> "Coordinator declared " + d + " DEAD (missed heartbeats)");
            queue.releaseClaimsOf(d);   // dead node's work returns to the queue
        });

        // Competing Consumers: worker-B picks up the released work.
        String reclaimed = queue.claim("worker-B", later);
        log.info(() -> "worker-B re-claimed released work: " + reclaimed);

        // Layer 3: resume from checkpoint instead of restarting.
        log.info("=== Layer 3: long job resumes from last checkpoint ===");
        CheckpointStore checkpoints = new CheckpointStore();
        // worker-A had checkpointed progress at offset 500,000 before dying.
        checkpoints.save("reconcile-EOD", 500_000L);
        ReconciliationJob job = new ReconciliationJob(checkpoints, 100_000);
        job.run("reconcile-EOD", 1_000_000L);   // resumes from 500,000, not 0
    }
}

// ─── coordinator/Coordinator.java (heartbeats + dead-node detection) ───
class Coordinator {
    private final long sessionTimeoutMs;
    private final Map<String, Long> lastBeat = new HashMap<>();
    Coordinator(long sessionTimeoutMs) { this.sessionTimeoutMs = sessionTimeoutMs; }
    void heartbeat(String workerId, long nowMs) { lastBeat.put(workerId, nowMs); }
    // Any worker whose last beat is older than the session timeout is declared dead.
    List<String> detectDead(long nowMs) {
        List<String> dead = new ArrayList<>();
        for (Map.Entry<String, Long> e : lastBeat.entrySet())
            if (nowMs - e.getValue() > sessionTimeoutMs) dead.add(e.getKey());
        dead.forEach(lastBeat::remove);
        return dead;
    }
}

// ─── queue/WorkQueue.java (lease release → Competing Consumers) ───
class WorkQueue {
    private final Deque<String> ready = new ArrayDeque<>();
    private final Map<String, String> claimedBy = new HashMap<>();  // item → worker
    void enqueue(String item) { ready.addLast(item); }
    String claim(String workerId, long nowMs) {
        String item = ready.pollFirst();
        if (item != null) claimedBy.put(item, workerId);
        return item;
    }
    // Dead node's claimed-but-unacked work returns to the queue for others.
    void releaseClaimsOf(String workerId) {
        List<String> released = new ArrayList<>();
        claimedBy.forEach((item, owner) -> { if (owner.equals(workerId)) released.add(item); });
        released.forEach(item -> { claimedBy.remove(item); ready.addFirst(item); });
    }
}

// ─── checkpoint/CheckpointStore.java ───
class CheckpointStore {
    private final Map<String, Long> offsets = new HashMap<>();
    void save(String jobId, long offset) { offsets.put(jobId, offset); }
    long load(String jobId) { return offsets.getOrDefault(jobId, 0L); }
}

// ─── job/ReconciliationJob.java (resume from checkpoint) ───
class ReconciliationJob {
    private static final Logger log = Logger.getLogger("RECOVER");
    private final CheckpointStore checkpoints; private final long checkpointEvery;
    ReconciliationJob(CheckpointStore checkpoints, long checkpointEvery) {
        this.checkpoints = checkpoints; this.checkpointEvery = checkpointEvery;
    }
    void run(String jobId, long totalItems) {
        long start = checkpoints.load(jobId);   // resume point
        log.info(() -> "Resuming " + jobId + " from offset " + start + " of " + totalItems + " (NOT from 0)");
        for (long i = start; i < totalItems; i += checkpointEvery) {
            long processedTo = Math.min(i + checkpointEvery, totalItems);
            checkpoints.save(jobId, processedTo);  // durable progress each batch
            log.fine(() -> "checkpoint " + jobId + " @ " + processedTo);
        }
        log.info(() -> "Completed " + jobId + " (only work after offset " + start + " was repeated)");
    }
}

// ─── retry/RetryExecutor.java ───
class RetryExecutor {
    private static final Logger log = Logger.getLogger("RECOVER");
    private final int maxAttempts; private final long baseDelayMs; private final boolean jitter;
    private final Random rnd = new Random(7);
    RetryExecutor(int maxAttempts, long baseDelayMs, boolean jitter) {
        this.maxAttempts = maxAttempts; this.baseDelayMs = baseDelayMs; this.jitter = jitter;
    }
    String run(String op, java.util.function.Supplier<String> action) {
        RuntimeException last = null;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try { return action.get(); }
            catch (RuntimeException e) {
                last = e;
                long backoff = (long) (baseDelayMs * Math.pow(2, attempt)) + (jitter ? rnd.nextInt(50) : 0);
                log.warning(() -> "Transient failure on " + op + " attempt " + attempt + "; retry in " + backoff + "ms");
            }
        }
        throw last;
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
